return [{
  json: {
    q: '삼성전자',
    naver_display: 20,
    naver_sort: 'date',
    serper_gl: 'kr',
    serper_hl: 'ko',
    serper_num: 20,
    serper_tbs: 'qdr:d'
  }
}];

const naver = $('T2. HTTP Request - Naver News').first().json || {};
const serper = $('T3. HTTP Request - Serper News').first().json || {};

function stripHtml(v) {
  return String(v || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ').trim();
}
function normUrl(u) {
  return String(u || '')
    .replace(/#.*$/, '')
    .replace(/[?&](utm_[^=&]+|nclick)=[^&]*/gi, '')
    .replace(/[?&]$/, '')
    .replace(/\/$/, '');
}
function titleKey(t) {
  return stripHtml(t).toLowerCase().replace(/[^0-9a-z가-힣]/g, '').slice(0, 70);
}
function dateValue(v) {
  const d = new Date(v || 0);
  return isNaN(d.getTime()) ? Date.now() : d.getTime();
}
function toIso(v) {
  const d = new Date(v || 0);
  return isNaN(d.getTime()) ? new Date().toISOString() : d.toISOString();
}

const naverArticles = (Array.isArray(naver.items) ? naver.items : []).map(r => ({
  title: stripHtml(r.title),
  url: String(r.originallink || r.link || '').trim(),
  source: 'Naver News',
  published_at_raw: r.pubDate || null,
  summary: stripHtml(r.description).slice(0, 300)
}));

const serperArticles = (Array.isArray(serper.news) ? serper.news : []).map(r => ({
  title: stripHtml(r.title),
  url: String(r.link || '').trim(),
  source: r.source || 'Serper News',
  published_at_raw: r.date || null,
  summary: stripHtml(r.snippet).slice(0, 300)
}));

const all = [...naverArticles, ...serperArticles].filter(a => a.title && a.url);

const seen = new Map();
for (const a of all) {
  const key = normUrl(a.url) + '|' + titleKey(a.title);
  if (!seen.has(key)) seen.set(key, a);
}

const deduped = [...seen.values()]
  .sort((a, b) => dateValue(b.published_at_raw) - dateValue(a.published_at_raw))
  .slice(0, 5)
  .map(a => ({
    title: a.title,
    url: a.url,
    source: a.source,
    published_at: toIso(a.published_at_raw),
    summary: a.summary
  }));

if (!deduped.length) {
  throw new Error('삼성전자 관련 최근 기사를 하나도 찾지 못했습니다. Naver/Serper 응답을 확인하세요.');
}

return [{ json: { articles: deduped } }];
